#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY so the garbage collector tracks it; a raw pointer was
	// purged by GC mid-game and the next goal dereferenced a dangling
	// pointer (EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker* ScoreTracker in AArenaGameMode (ArenaGameMode.h) was a raw C++ pointer with no UPROPERTY, so the Unreal garbage collector could not see it. After GC ran mid-game (log 21:05.13 'Collecting garbage: 412 objects purged') the tracker object was purged, leaving a dangling pointer; the next goal (log 21:05.27) called ScoreTracker->AddPoints() on it, crashing with EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints (ArenaScoreTracker.cpp:18), called from AArenaGameMode::OnGoalScored (ArenaGameMode.cpp:38). Fix: declared ScoreTracker as UPROPERTY (TObjectPtr) in ArenaGameMode.h so GC tracks it.",
  "no_colors_cause": "The arena colors come from the data asset /Game/Data/Palettes/DA_Primary, loaded at runtime by hard-coded path via LoadObject in AArenaGameMode::BeginPlay. Because it is not referenced by any UPROPERTY, the cooker never sees it as a dependency of the map; with bCookAll=False and only /Game/Maps/Arena cooked (plus /Game/Data/Effects always cooked), the palette package was not cooked into the packaged build (log 21.04.12 'Couldn't find file for package /Game/Data/Palettes/DA_Primary'). Palette loaded null, BeginPlay logged 'Palette is null, using fallback gray', and the HUD rendered gray. Fix: added /Game/Data/Palettes to DirectoriesToAlwaysCook in Config/DefaultGame.ini so the runtime-loaded palette is always cooked."
}
